const nextKnowledgeScanCandidate = `-- name: NextKnowledgeScanCandidate :one
SELECT candidate.id, candidate.target_kind, candidate.target_workspace_id, candidate.target_project_id
FROM collaboration_knowledge_candidate candidate
WHERE candidate.published_target_revision IS NOT NULL
    AND candidate.id <= $1::uuid
    AND ($2::uuid IS NULL OR candidate.id > $2::uuid)
    AND ($3::text = 'all_sources'
        OR $3::text = 'source_issue' AND candidate.source_issue_id = $4::uuid
        OR $3::text = 'source_workspace' AND candidate.source_workspace_id = $4::uuid)
ORDER BY candidate.id LIMIT 1
`

